_choice_winget_installed() {
    _argc_util_cache 60 _choice_winget_installed_uncached winget-installed
}

_choice_winget_installed_uncached() {
    winget list --accept-source-agreements --disable-interactivity 2>/dev/null | _helper_winget_ids
}

_choice_winget_pinned() {
    _argc_util_cache 60 _choice_winget_pinned_uncached winget-pinned
}

_choice_winget_pinned_uncached() {
    winget pin list --accept-source-agreements --disable-interactivity 2>/dev/null | _helper_winget_ids
}

_choice_winget_source() {
    _argc_util_cache 300 _choice_winget_source_uncached winget-sources
}

_choice_winget_source_uncached() {
    winget source list 2>/dev/null | gawk '/:\/\// { print $1 }'
}

_choice_winget_upgradable() {
    _argc_util_cache 60 _choice_winget_upgradable_uncached winget-upgradable
}

_choice_winget_upgradable_uncached() {
    winget upgrade --include-unknown --accept-source-agreements --disable-interactivity 2>/dev/null | _helper_winget_ids
}

_helper_winget_ids() {
    gawk '
        function isver(t) { return t ~ /^[0-9]+([.][0-9A-Za-z]+)+$/ }
        {
            n = split($0, a, /[[:space:]]+/)
            m = 0
            for (i = 1; i <= n; i++) {
                if (a[i] != "") {
                    m++
                    b[m] = a[i]
                }
            }
            if (m == 0) {
                next
            }
            i = m
            if (!isver(b[i]) && !index(b[i], ".") && !index(b[i], "\\")) {
                i--
            }
            while (i >= 1 && isver(b[i])) {
                i--
            }
            if (i < 1) {
                next
            }
            if (index(b[i], ".") || index(b[i], "\\")) {
                print b[i]
            }
        }
    '
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
